export declare const GLOSSARY_STYLESHEET = "\n.rx-glossary-search {\n  display: flex;\n  align-items: center;\n  padding: var(--rx-space-2) var(--rx-space-3);\n  border-bottom: 1px solid var(--rx-border);\n  flex: 0 0 auto;\n}\n.rx-glossary-search-input {\n  flex: 1 1 auto;\n  min-height: 48px;\n  padding: 0 var(--rx-space-2);\n  border: 1px solid var(--rx-border);\n  border-radius: var(--rx-radius);\n  background: var(--rx-ground);\n  color: var(--rx-ink);\n  font-size: 14px;\n}\n.rx-glossary-list {\n  position: absolute;\n  inset: 0;\n  top: 65px; /* below the fixed-height search bar */\n  overflow-y: auto;\n}\n.rx-glossary-item {\n  padding: var(--rx-space-2) var(--rx-space-3);\n  border-bottom: 1px solid var(--rx-border);\n}\n.rx-glossary-term-row {\n  min-height: 48px;\n  display: flex;\n  align-items: center;\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--rx-ink);\n  cursor: pointer;\n  background: none;\n  border: none;\n  width: 100%;\n  text-align: left;\n  padding: 0;\n}\n.rx-glossary-def {\n  font-size: 12px;\n  color: var(--rx-muted);\n  margin-top: 3px;\n  line-height: 1.45;\n  display: none;\n}\n.rx-glossary-item.expanded .rx-glossary-def {\n  display: block;\n}\n.rx-glossary-empty {\n  padding: var(--rx-space-4) var(--rx-space-3);\n  text-align: center;\n  font-size: 13px;\n  color: var(--rx-muted);\n}\n.rx-glossary-item.flash {\n  background: var(--rx-surface-2);\n}\n\n.rx-glossary-popover {\n  position: absolute;\n  z-index: 90;\n  background: var(--rx-surface);\n  color: var(--rx-ink);\n  border: 1px solid var(--rx-border);\n  border-radius: var(--rx-radius);\n  box-shadow: var(--rx-elevation); /* taste-skill-ignore: a true floater (role=dialog popover), the app-screens shadow exception */\n  padding: var(--rx-space-2) var(--rx-space-3) var(--rx-space-3);\n  width: max-content;\n  min-width: 168px;\n  max-width: min(288px, calc(100% - 16px));\n  animation: rx-glossary-pop-in var(--rx-motion-fast) ease;\n}\n.reader-shell.e-ink .rx-glossary-popover,\n.reader-shell.reduced-motion .rx-glossary-popover {\n  animation: none;\n}\n@keyframes rx-glossary-pop-in {\n  from {\n    opacity: 0;\n    transform: scale(0.96);\n  }\n  to {\n    opacity: 1;\n    transform: scale(1);\n  }\n}\n.rx-glossary-popover-head {\n  display: flex;\n  align-items: center;\n  gap: var(--rx-space-2);\n}\n.rx-glossary-popover-term {\n  margin: 0;\n  flex: 1 1 auto;\n  min-width: 0;\n  font-size: 15px;\n  font-weight: 600;\n  line-height: 1.3;\n}\n.rx-glossary-popover-def {\n  margin: var(--rx-space-1) 0 0;\n  font-size: 14px;\n  line-height: 1.45;\n}\n.rx-glossary-popover-open {\n  flex: 0 0 auto;\n  width: 44px;\n  height: 44px;\n  color: var(--rx-accent);\n}\n";
